#!/usr/bin/env bash
# shellcheck source-path=SCRIPTDIR
# shellcheck disable=SC2001
# strip-snapshot-version.sh — Strip -SNAPSHOT from the project <version> (never the <parent> version) for release builds.
#
# GENERATED by tests/parity/extract_inline_bash.py — do not hand-edit (change the Azure source or
# the extractor, then run it with --write). Extracted from the Azure DevOps inline step:
#   source : platforms/azure-devops/mulesoft-pipeline-templates/pipelines/templates/stages/build.yml
#   step   : "Strip SNAPSHOT Version" (Bash@3 inline)
# The body is that step verbatim, except: ##vso commands -> ci-shim calls, Azure predefined
# variables -> ci-shim normalizers, and $(...) / ${{ parameters.* }} macros -> the MDF_* inputs below.
# The shellcheck codes disabled above come from constructs inherited verbatim from that source.
#
# Outputs: RELEASE_VERSION (job env)

# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

# >>> extracted body
set -euo pipefail
SOURCE_POM="$(ci_default_working_directory)/pom.xml"

# Extract project version from pom.xml (skip <parent> block)
PARENT_END_LINE=$(grep -n '</parent>' "$SOURCE_POM" | head -1 | cut -d: -f1)
if [[ -n "$PARENT_END_LINE" ]]; then
  CURRENT_VERSION=$(tail -n +"$((PARENT_END_LINE + 1))" "$SOURCE_POM" | grep '<version>' | head -1 | sed 's/.*<version>\(.*\)<\/version>.*/\1/' | tr -d '[:space:]')
else
  CURRENT_VERSION=$(grep '<version>' "$SOURCE_POM" | head -1 | sed 's/.*<version>\(.*\)<\/version>.*/\1/' | tr -d '[:space:]')
fi

if [[ -z "$CURRENT_VERSION" ]]; then
  ci_log_error "Failed to extract project version from pom.xml."
  exit 1
fi
echo "[DEBUG] Current version: $CURRENT_VERSION"

RELEASE_VERSION=$(echo "$CURRENT_VERSION" | sed 's/-SNAPSHOT//')

if [[ "$CURRENT_VERSION" == "$RELEASE_VERSION" ]]; then
  echo "Version $CURRENT_VERSION is already a release version. No stripping needed."
else
  echo "Stripping SNAPSHOT: $CURRENT_VERSION -> $RELEASE_VERSION"
  # Rewrite ONLY the project's <version>, never the <parent> version.
  # The parent and project versions can be identical (both
  # 1.0.0-SNAPSHOT), so a plain 'sed 0,/.../' first-match hits the
  # parent's <version> (which appears first) and strips IT to a
  # release version — making the build request a parent POM release
  # that was never published (401/absent). Restrict the substitution
  # to the FIRST matching <version> at or after the line following
  # </parent>, mirroring how CURRENT_VERSION is read above.
  STRIP_FROM=1
  [[ -n "$PARENT_END_LINE" ]] && STRIP_FROM=$((PARENT_END_LINE + 1))
  awk -v from="$STRIP_FROM" -v cur="<version>${CURRENT_VERSION}</version>" -v rel="<version>${RELEASE_VERSION}</version>" '
    NR >= from && !done {
      idx = index($0, cur)
      if (idx > 0) { sub(cur, rel); done = 1 }
    }
    { print }
  ' "$SOURCE_POM" > "${SOURCE_POM}.tmp" && mv "${SOURCE_POM}.tmp" "$SOURCE_POM"
fi

ci_set_env RELEASE_VERSION "$RELEASE_VERSION"
echo "[DEBUG] RELEASE_VERSION set to: $RELEASE_VERSION"
